// Basic numeric and string literal deduction
auto count = 10;            // Deduced as int
auto ratio = 1.0 / 3.0;     // Deduced as double
auto name = "Deduction";    // Deduced as const char*

// Handling STL containers (avoiding verbose types)
std::vector<int> numbers;
for (auto it = numbers.begin(); it != numbers.end(); ++it) {}

// Range-based loop optimization
std::map<int, float> scores;
for (const auto& entry : scores) { /* entry is const std::pair<const int, float>& */ }

// Reference and Const Qualifier Preservation
int x = 42;
const int& ref_x = x;
auto a = ref_x;     // a is int (drops const and reference)
auto& ar = ref_x;   // ar is const int& (preserves const and reference)

// Capturing complex return types (e.g., lambda)
auto complex_func = [](int a) { return a * 2.5; };
auto result = complex_func(5); // result is double
